// using System;
// using System.Collections.Generic;

var inn = this.getInnovator();

try
{
    string getData = getItemData(inn);
    return inn.newResult(getData);
}
catch (Exception e)
{
    return inn.newError("Error:" + e.Message + e.StackTrace);
}


// データを作成
String getItemData(Innovator inn)
{
    //対象マルQページのIDを取得
    string MQPageid = this.getProperty("itemId");
    Item MQPage = inn.getItemById("h4_MQPage", MQPageid);
    //機種を取得
    string projid = MQPage.getProperty("h4_model_name");
    // イベントを取得
    string events = MQPage.getProperty("h4_event");
    //Item eventList = getEventData(inn);
    //　次数を取得
    string counts = MQPage.getProperty("h4_approval_round");
    // 一次、二次、三次…の値を格納するリスト
    var eventValueList = new List<string>();
    // ラベルを格納するリスト
    var eventHeader = new List<string>();
    var debug = "NG";
    // 一次、二次…をeventvalue配列に格納していく
    for (int eventNum = 1; eventNum <= int.Parse(counts); eventNum++)
    {
        eventValueList.Add(eventNum.ToString());
        string label = events + " " + eventNum.ToString() + "次";
        eventHeader.Add(label);
    }
    string eventAML = String.Join("','", eventValueList.ToArray());

    //アイテムタイプ名は固定
    string propertyString = "h4_ReqDoc";

    string JsonStr = "[";

    // 取得したアイテムタイプ名が空じゃない場合のみ表示処理する    
    string[] itemTypeArray = propertyString.Split(',');
    var getItemType = itemTypeArray;
    var tempLabel = "";// 一つ前のアイテムのアイテムタイプを保持する変数
    var rowSum = 0;

    // フィルタされたサマリー表に表示するイベントを[,]に区切られた文字列として、戻り値用アイテムに追加
    string eventListStr = String.Join("','", eventValueList.ToArray());
    // サマリー表に表示するイベントのラベル名リストを[,]に区切られた文字列に
    string eventLabelStr = String.Join("','", eventHeader.ToArray());

    //親マルQページに紐づく必要資料アイテムをsort_order昇順で取得
    string AML = "<AML>"
                + "<Item type='h4_MQPage' action='get'>"
                + "<id>" + MQPageid + "</id>"
                + "<Relationships><Item type='h4_MQPage ReqDoc' action='get' orderBy='sort_order asc'>"
                + "<select>*</select></Item></Relationships></Item></AML>";
    Item tempItem = inn.applyAML(AML);

    //必要資料の重複なし資料名(室課)一覧を取得
    var DocList = new List<string>();
    Item tempRecDocs = tempItem.getRelationships("h4_MQPage ReqDoc");
    Item itemData = inn.newItem("h4_ReqDoc");
    for (int i = 0; i < tempRecDocs.getItemCount(); i++)
    {
        Item tempRecDoc = tempRecDocs.getItemByIndex(i).getRelatedItem();
        itemData.appendItem(tempRecDoc);
        string DocNames = tempRecDoc.getProperty("h4_datformat_name");
        
        if (!DocList.Contains(DocNames))
        {
            DocList.Add(DocNames);
        }
    }
    itemData.removeItem(itemData.getItemByIndex(0));
    
    // throw new Exception(itemData.ToString());
    
    string DocListStr = String.Join("','", DocList.ToArray());

    //戻り値のJson先頭にイベント値、イベントラベル、資料一覧を定義する
    JsonStr += "{" + "'eventValueList':['" + eventListStr + "'],"
            + "'eventHeader':['" + eventLabelStr + "'],"
            + "'DocList':['" + DocListStr + "']"
            + "}";

    /* アイテムタイプ名（ラベル）を取得
    var itemLabel = itemTypeName;
    Item itmLabel = inn.newItem("ItemType", "get");
    itmLabel.setProperty("name", itemTypeName);
    itmLabel = itmLabel.apply();
    if (itmLabel.getItemCount() == 1)
    {
        itemLabel = itmLabel.getProperty("label");
        itemTypeName = itmLabel.getProperty("name");
    }
    int rowNum = 0;
    */
    var itemLabel = "必要資料";
    var itemTypeName = "h4_ReqDoc";
    //各アイテムのプロパティを取得
    for (int j = 0; j < itemData.getItemCount(); j++)
    {
        // 更新日を取得
        string modifiedondate = itemData.getItemByIndex(j).getProperty("modified_on");
        // Date型に変換
        DateTime modifiedon = DateTime.Parse(modifiedondate);
        // 年、月、日、時、分を取得
        string ymd = modifiedon.ToString("d");
        string hm = modifiedon.ToString("t");
        string modifiedOn = ymd + " T" + hm;

        // 更新者を取得
        string modifiedBy = itemData.getItemByIndex(j).getProperty("modified_by_id");
        string modifiedByMan = getUserName(inn, modifiedBy);

        // 作成日を取得
        string createdondate = itemData.getItemByIndex(j).getProperty("created_on");
        // Date型に変換
        DateTime createdon = DateTime.Parse(createdondate);
        // 年、月、日、時、分を取得
        string creymd = createdon.ToString("d");
        string crehm = createdon.ToString("t");

        // 20XX/0X/0X AA:BBの形式に変換して表示
        string createdOn = creymd + " T" + crehm;

        // 作成者を取得
        string createdBy = itemData.getItemByIndex(j).getProperty("created_by_id");
        string createdByMan = getcreUserName(inn, createdBy);

        // アイテムIDを取得
        string itemId = itemData.getItemByIndex(j).getProperty("id");

        // アイテム名を取得
        string itemNameLabel = itemData.getItemByIndex(j).getProperty("keyed_name");

        // ステータスを取得
        string currentStateID = itemData.getItemByIndex(j).getProperty("current_state");
        string itemStatus = getItemStatus(inn, currentStateID);

        // 資料名を取得
        string DocName = itemData.getItemByIndex(j).getProperty("h4_datformat_name");

        // やるやらを取得
        string yaruyaraSet = itemData.getItemByIndex(j).getProperty("h4_yryr");
        string yaruyara = "";
        switch (yaruyaraSet)
        {
            case "1":
                yaruyara = "○";
                break;
            case "0":
                yaruyara = "×";
                break;
        }

        // やるやら理由を取得
        string memo = itemData.getItemByIndex(j).getProperty("h4_yryr_reason");

        // 次数を取得
        string approval_round = itemData.getItemByIndex(j).getProperty("h4_approval_round");
        // string approval_round = approval_round_num.ToString();

        //項目分類を取得
        string yryr_class = itemData.getItemByIndex(j).getProperty("h4_yryr_classification");

        string creatorName = "";
        string approverName = "";
        string approvedDate = "";

        // 作成者と承認者を取得
        // 担当一覧のリレーション名を取得する
        // →担当一覧のリレーション名は各アイテムタイプ名 + " CLN"で作成している
        string relCLName = itemTypeName + " CLN";
        Item thisItem = inn.getItemById(itemTypeName, itemId);
        thisItem.fetchRelationships(relCLName);

        Item relCLItem = thisItem.getRelationships(relCLName);

        for (int m = 0; m < relCLItem.getItemCount(); m++)
        {
            string rolestr = relCLItem.getItemByIndex(m).getProperty("h4_workflow_role");
            switch (rolestr)
            {
                case "Approver":
                    string approverId = relCLItem.getItemByIndex(m).getProperty("related_id");
                    if (!string.IsNullOrEmpty(approverId))
                    {
                        Item apIdentityItem = inn.getItemById("Identity", approverId);
                        approverName = apIdentityItem.getProperty("name");
                    }
                    break;
                case "Creater":
                    string creatorId = relCLItem.getItemByIndex(m).getProperty("related_id");
                    if (!string.IsNullOrEmpty(creatorId))
                    {
                        Item crIdentityItem = inn.getItemById("Identity", creatorId);
                        creatorName = crIdentityItem.getProperty("name");
                    }
                    break;
            }
        }
 
         // ワークフローの終了日取得
        // ワークフロープロセス取得
        Item workflowProcess = inn.newItem("Workflow Process", "get");
        workflowProcess.setAttribute("select", "id");
        workflowProcess.setProperty("state", "Closed");
        Item workflow = inn.newItem("Workflow", "get");
        workflow.setAttribute("select", "source_id,related_id");
        workflow.setProperty("source_id", itemId);
        workflow.setRelatedItem(workflowProcess);
        workflow = workflow.apply();
        if (workflow.getItemCount() > 0)
        {
            string workflowProcessId = workflow.getRelatedItem().getID();
            Item WFPItem = inn.getItemById("Workflow Process", workflowProcessId);
            string closedDateStr = WFPItem.getProperty("closed_date");
            // Date型に変換
            DateTime closedDate = DateTime.Parse(closedDateStr);
            // 年、月、日、時、分を取得
            string clsymd = closedDate.ToString("d");
            string clshm = closedDate.ToString("t");
            // 20XX/0X/0X AA:BBの形式に変換して表示
            approvedDate = clsymd + " T" + clshm;
        }
        
        //fileidを取得(１つだけ)
        string fileName = "";
        string fileId = "";

        //ソースアイテムタイプのID取得
        Item sourceItem = inn.newItem("ItemType", "get");
        sourceItem.setProperty("keyed_name", itemTypeName);
        Item sourceResult = sourceItem.apply();
        string sourceId = sourceResult.getID();

        //リレーテッドアイテムのID取得(Document)
        Item relatedItem = inn.newItem("ItemType", "get");
        relatedItem.setProperty("keyed_name", "Document");
        Item relatedResult = relatedItem.apply();
        string relatedId = relatedResult.getID();

        //Documentとのリレーションシップアイテムタイプ取得
        Item relationshipType = inn.newItem("RelationshipType", "get");
        relationshipType.setProperty("source_id", sourceId);
        relationshipType.setProperty("related_id", relatedId);
        Item filRelTypeData = relationshipType.apply();

        if (filRelTypeData.getItemCount() > 0)
        {
            string filRelitemName = filRelTypeData.getProperty("name");

            //Documentとのリレーションシップアイテム取得
            Item relatedItemType = inn.newItem(filRelitemName, "get");
            relatedItemType.setProperty("source_id", itemId);
            Item filRelitemData = relatedItemType.apply();
            if (filRelitemData.getItemCount() > 0)
            {
                for (int k = 0; k < filRelitemData.getItemCount(); k++)
                {
                    string docTypeId = filRelitemData.getItemByIndex(k).getProperty("related_id");
                    Item docItem = inn.getItemById("Document", docTypeId);
                    fileId = docItem.getItemByIndex(0).getProperty("file_item");
                    fileName = docItem.getItemByIndex(0).getProperty("name");
                    
                    // 必要情報をJson文字列に設定
                    JsonStr += ",{" + "'itemnamelabel':'" + itemNameLabel + "',"
                        + "'itemtypename':'" + itemTypeName + "',"
                        + "'itemid':'" + itemId + "',"
                        + "'fileid':'" + fileId + "',"
                    + "'fileName':'" + fileName + "',"
                    + "'modifyon':'" + modifiedOn + "',"
                    + "'modifyby':'" + modifiedByMan + "',"
                    + "'itemstatus':'" + itemStatus + "',"
                    + "'createon':'" + createdOn + "',"
                    + "'createby':'" + createdByMan + "',"
                    + "'itemtypelabel':'" + itemLabel + "',"
                    + "'approvalround':'" + approval_round + "',"
                    + "'docname':'" + DocName + "',"
                    + "'yaruyara':'" + yaruyara + "',"
                    + "'memo':'" + memo + "',"
                    + "'yryr_class':'" + yryr_class + "',"
                    + "'creatorName':'" + creatorName + "',"
                    + "'approverName':'" + approverName + "',"
                    + "'approvedDate':'" + approvedDate + "'" + "}";
                }
            }else
            {
               // 必要情報をJson文字列に設定
                JsonStr += ",{" + "'itemnamelabel':'" + itemNameLabel + "',"
                    + "'itemtypename':'" + itemTypeName + "',"
                    + "'itemid':'" + itemId + "',"
                    + "'fileid':'" + fileId + "',"
                    + "'fileName':'" + fileName + "',"
                    + "'modifyon':'" + modifiedOn + "',"
                    + "'modifyby':'" + modifiedByMan + "',"
                    + "'itemstatus':'" + itemStatus + "',"
                    + "'createon':'" + createdOn + "',"
                    + "'createby':'" + createdByMan + "',"
                    + "'itemtypelabel':'" + itemLabel + "',"
                    + "'approvalround':'" + approval_round + "',"
                    + "'docname':'" + DocName + "',"
                    + "'yaruyara':'" + yaruyara + "',"
                    + "'memo':'" + memo + "',"
                    + "'yryr_class':'" + yryr_class + "',"
                    + "'creatorName':'" + creatorName + "',"
                    + "'approverName':'" + approverName + "',"
                    + "'approvedDate':'" + approvedDate + "'" + "}";
            }
        }
        /*
        
        // 必要情報をJson文字列に設定
        JsonStr += ",{" + "'itemnamelabel':'" + itemNameLabel + "',"
            + "'itemtypename':'" + itemTypeName + "',"
            + "'itemid':'" + itemId + "',"
            + "'fileid':'" + fileId + "',"
            + "'fileName':'" + fileName + "',"
            + "'modifyon':'" + modifiedOn + "',"
            + "'modifyby':'" + modifiedByMan + "',"
            + "'itemstatus':'" + itemStatus + "',"
            + "'createon':'" + createdOn + "',"
            + "'createby':'" + createdByMan + "',"
            + "'itemtypelabel':'" + itemLabel + "',"
            + "'approvalround':'" + approval_round + "',"
            + "'docname':'" + DocName + "',"
            + "'yaruyara':'" + yaruyara + "',"
            + "'memo':'" + memo + "',"
            + "'creatorName':'" + creatorName + "',"
            + "'approverName':'" + approverName + "',"
            + "'approvedDate':'" + approvedDate + "'" + "}";
            // + "'approverName':'" + approverName + "'" + "}";
*/

    }
    JsonStr += "]";
    return JsonStr;
    //return debug;

}

// イベントを取得f
Item getEventData(Innovator inn)
{
    // 取得したいリスト名を指定
    string listName = "h4_Events";
    // List アイテムを検索
    Item listItem = inn.newItem("List", "get");
    listItem.setProperty("keyed_name", listName);
    Item result = listItem.apply();
    // 子要素（値）を取得
    result.fetchRelationships("Value");
    Item values = result.getRelationships("Value");
    return values;
}

// 更新者のユーザー名を取得
string getUserName(Innovator inn, String userid)
{
    if (userid == "")
    {
        return "更新者不明";
    }
    Item item = inn.getItemById("User", userid);
    return item.getProperty("keyed_name", "");
}
// 作成者のユーザー名を取得
string getcreUserName(Innovator inn, String userid)
{
    if (userid == "")
    {
        return "作成者不明";
    }
    Item item = inn.getItemById("User", userid);
    return item.getProperty("keyed_name", "");
}
// 日本語のステータスを取得
String getItemStatus(Innovator inn, String stateid)
{
    if (stateid == "")
    {
        return "";
    }
    Item item = inn.getItemById("Life Cycle State", stateid);
    return item.getProperty("label", "");
}

